$ErrorActionPreference='Stop'
Set-StrictMode -Version 2.0
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
. (Join-Path $root 'validation/custom-app-production-dual-id-new-permit-reservation-v0.1.0/test_custom_app_production_dual_id_new_permit_reservation.ps1')
. (Join-Path $PSScriptRoot 'custom-app-production-dual-id-new-permit-reservation-persistence.ps1')

function Assert-DINPPTrue([bool]$v,[string]$m){if(-not $v){throw $m}}
function Assert-DINPPFalse([bool]$v,[string]$m){if($v){throw $m}}
function Assert-DINPPEq($a,$b,[string]$m){if([string]$a -cne [string]$b){throw "$m actual=<$a> expected=<$b>"}}
function Copy-DINPP($x){return (($x|ConvertTo-Json -Depth 100)|ConvertFrom-Json)}
function Assert-DINPPZeroAuthority($r,[string]$label){foreach($f in @('session_key_persisted','session_key_exposed','permit_consumed','persistence_is_authority','executor_may_start','production_execution_authorized','production_mutation_authorized')){if($r.PSObject.Properties[$f]){Assert-DINPPFalse ([bool]$r.$f) "$label authority escaped $f"}}}
function Assert-DINPPDenied($r,[string]$label){Assert-DINPPFalse ([bool]$r.ok) "$label unexpectedly persisted";Assert-DINPPZeroAuthority $r $label}

# The qualified #203 reservation test above already produced a byte-real valid reservation
# fixture and result before this child validation starts. Reuse that proven seed and
# allocate only a fresh persistence store per case. Re-entering New-DINPRFixtureV010
# after the inherited test stack has finished would re-enter historical globally-named
# fixture helpers whose names intentionally collide across isolated validation harnesses.
if($null-eq$valid-or$null-eq$validResult){throw 'qualified reservation seed fixtures were not retained by parent test'}
$script:DINPPPrimaryQ=$valid
$script:DINPPPrimaryReservation=$validResult
Assert-DINPPTrue ([bool]$script:DINPPPrimaryReservation.ok) 'primary qualified reservation seed invalid'

function New-DINPPFixtureV010 {
    param([Parameter(Mandatory=$true)][string]$Label)
    $q=$script:DINPPPrimaryQ
    $reservation=$script:DINPPPrimaryReservation
    $at=$q.at.AddMilliseconds(500)
    $rc=Test-CustomAppProductionDualIdNewPermitReservationReceiptV010 -Receipt $reservation.receipt -Now $at
    Assert-DINPPTrue ([bool]$rc.ok) ("$Label qualified reservation seed receipt invalid: $([string]$rc.reason)")
    $store=Join-Path $q.i.f.q.x.f.trust ('dual-id-reservation-store-'+[Guid]::NewGuid().ToString('N'))
    $history=Join-Path $store 'history';[IO.Directory]::CreateDirectory($history)|Out-Null
    return [pscustomobject]@{q=$q;reservation=$reservation;store=$store;at=$at}
}
function Invoke-DINPPV010 {
    param([Parameter(Mandatory=$true)]$P,[AllowNull()]$ReservationResult=$null,[AllowNull()]$IssuerResult=$null,[AllowNull()][byte[]]$Key=$null,[AllowNull()]$Bundle=$null,[AllowNull()]$CurrentBaseline=$null,[AllowNull()][string]$PersistenceStore=$null,[DateTimeOffset]$At=[DateTimeOffset]::MinValue,[ValidateSet('none','after-history-before-current')][string]$FailurePoint='none')
    $Q=$P.q;$I=$Q.i;$F=$I.f
    if($null -eq $ReservationResult){$ReservationResult=$P.reservation};if($null -eq $IssuerResult){$IssuerResult=$Q.issuer};if($null -eq $Key){$Key=$script:DINPIKey};if($null -eq $Bundle){$Bundle=$F.q.bundle};if($null -eq $CurrentBaseline){$CurrentBaseline=$F.live.baseline};if([string]::IsNullOrWhiteSpace($PersistenceStore)){$PersistenceStore=$P.store};if($At -eq [DateTimeOffset]::MinValue){$At=$P.at}
    return Invoke-CustomAppProductionDualIdNewPermitReservationPersistenceV010 -Name ([string]$Bundle.lifecycle.name) -LifecycleRow $Bundle.lifecycle -ProvenanceRow $Bundle.provenance -BindingRow $Bundle.binding -StageResult $Bundle.stage -ShadowResult $Bundle.shadow -HousekeepingResult $F.q.house.result -AllowedRoot $F.q.x.f.trust -RecoveryStoreDirectory $F.q.x.f.store -PersistenceStoreDirectory $PersistenceStore -HistoricalPermitTransactionId ([string]$F.q.house.result.permit_transaction_id) -HistoricalJournalTransactionId ([string]$F.q.house.result.journal_transaction_id) -NewPermitTransactionId ([string]$F.new_id) -LocalAppDataRoot ([string]$F.q.x.f.x.fixture.q.persistence.local) -AppDataRoot ([string]$F.q.x.f.x.fixture.q.persistence.roaming) -CurrentBaseline $CurrentBaseline -ShadowProtocolQualification $F.live.shadow -LiveAttestedQualification $F.live.live -PriorReadinessReceipt $F.prior -IssuanceAdmissionReceipt $I.admission -IssuerResult $IssuerResult -SessionKey $Key -ReservationResult $ReservationResult -Now $At -FailurePoint $FailurePoint
}

$count=0
$valid=New-DINPPFixtureV010 'valid';$r=Invoke-DINPPV010 $valid
Assert-DINPPTrue ([bool]$r.ok) ('valid persistence denied: '+[string]$r.reason);Assert-DINPPEq $r.reason 'dual-id-new-permit-reservation-durably-persisted-zero-authority' 'valid persistence reason';Assert-DINPPTrue ([bool]$r.reservation_persisted) 'valid reservation not persisted';Assert-DINPPTrue ([bool]$r.nonce_durably_reserved) 'valid nonce not durable';Assert-DINPPTrue ([bool]$r.permit_durably_reserved) 'valid permit not durable';Assert-DINPPFalse ([bool]$r.permit_consumed) 'valid permit consumed early';Assert-DINPPTrue ([bool]$r.transaction_binding_revalidated) 'valid binding not revalidated';Assert-DINPPEq $r.receipt.new_permit_transaction_id $valid.q.i.f.new_id 'valid new transaction id';Assert-DINPPEq $r.store.envelope.new_permit_transaction_id $valid.q.i.f.new_id 'durable envelope new transaction id';Assert-DINPPEq $r.store.envelope.historical_permit_transaction_id $valid.q.i.f.q.house.result.permit_transaction_id 'durable old permit id';Assert-DINPPEq $r.store.envelope.historical_journal_transaction_id $valid.q.i.f.q.house.result.journal_transaction_id 'durable journal id';Assert-DINPPEq $r.store.envelope.transaction_binding_hmac_sha256 $valid.q.issuer.receipt.transaction_binding_hmac_sha256 'durable transaction HMAC';Assert-DINPPZeroAuthority $r 'valid';$read=Read-CustomAppProductionDualIdNewPermitReservationStoreV010 -AllowedRoot $valid.q.i.f.q.x.f.trust -PersistenceStoreDirectory $valid.store;Assert-DINPPTrue ([bool]$read.ok) 'valid durable read denied';Assert-DINPPEq $read.current_status 'matches-latest' 'valid current pointer';Assert-DINPPEq $read.revision 1 'valid revision';$serialized=$read.envelope|ConvertTo-Json -Depth 100 -Compress;$keyHex=(-join ($script:DINPIKey|ForEach-Object{$_.ToString('x2')}));$keyB64=[Convert]::ToBase64String($script:DINPIKey);Assert-DINPPFalse ($serialized.Contains($keyHex) -or $serialized.Contains($keyB64)) 'serialized durable envelope contains session-key material';$validResult=$r;$count++

$retryAt=$valid.q.at.AddSeconds(3.2);$retry=Invoke-DINPPV010 -P $valid -At $retryAt;Assert-DINPPTrue ([bool]$retry.ok) ('exact retry denied: '+[string]$retry.reason);Assert-DINPPTrue ([bool]$retry.store.recovered_existing_persistence) 'exact retry did not recover existing persistence';Assert-DINPPFalse ([bool]$retry.store.write_performed) 'exact retry rewrote durable history';$read2=Read-CustomAppProductionDualIdNewPermitReservationStoreV010 -AllowedRoot $valid.q.i.f.q.x.f.trust -PersistenceStoreDirectory $valid.store;Assert-DINPPEq $read2.history_count 1 'exact retry duplicated history';$count++

$crash=New-DINPPFixtureV010 'crash';$first=Invoke-DINPPV010 -P $crash -FailurePoint 'after-history-before-current';Assert-DINPPDenied $first 'simulated history/current crash';Assert-DINPPTrue ([bool]$first.reservation_persisted) 'crash did not report durable history';$paths=Get-CustomAppProductionDualIdNewPermitReservationPersistencePathsV010 -AllowedRoot $crash.q.i.f.q.x.f.trust -PersistenceStoreDirectory $crash.store;Assert-DINPPFalse (Test-Path -LiteralPath $paths.current) 'simulated crash unexpectedly wrote current';$recovered=Invoke-DINPPV010 -P $crash -At $crash.at.AddMilliseconds(200);Assert-DINPPTrue ([bool]$recovered.ok) ('crash retry denied: '+[string]$recovered.reason);Assert-DINPPTrue ([bool]$recovered.store.recovered_existing_persistence) 'crash retry not recognized as recovery';Assert-DINPPTrue ([bool]$recovered.store.repaired_current_pointer) 'crash retry did not repair current pointer';$strict=Read-CustomAppProductionDualIdNewPermitReservationStoreV010 -AllowedRoot $crash.q.i.f.q.x.f.trust -PersistenceStoreDirectory $crash.store;Assert-DINPPEq $strict.current_status 'matches-latest' 'repaired current not strict-readable';Assert-DINPPEq $strict.history_count 1 'crash recovery duplicated history';$count++

$lock=New-DINPPFixtureV010 'lock';$lp=Get-CustomAppProductionDualIdNewPermitReservationPersistencePathsV010 -AllowedRoot $lock.q.i.f.q.x.f.trust -PersistenceStoreDirectory $lock.store;$held=Open-CustomAppProductionDualIdNewPermitReservationPersistenceLockV010 -Paths $lp;try{$x=Invoke-DINPPV010 $lock}finally{$held.Dispose()};Assert-DINPPDenied $x 'lock contention';Assert-DINPPTrue ([string]$x.reason -like '*lock-busy*') ('lock reason '+[string]$x.reason);Assert-DINPPFalse (Test-Path -LiteralPath $lp.current) 'lock contention wrote current';$count++

$escape=New-DINPPFixtureV010 'escape';$allowed=[IO.Path]::GetFullPath([string]$escape.q.i.f.q.x.f.trust).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar);$allowedParent=[IO.Directory]::GetParent($allowed);if($null -eq $allowedParent){throw 'path escape fixture allowed-root parent missing'};$outside=Join-Path $allowedParent.FullName ('dinpp-outside-'+[Guid]::NewGuid().ToString('N'));if(Test-CustomAppProductionDualIdNewPermitReservationPersistenceWithinV010 -Root $allowed -Path $outside){throw 'path escape fixture failed to construct outside path'};[IO.Directory]::CreateDirectory($outside)|Out-Null;[IO.Directory]::CreateDirectory((Join-Path $outside 'history'))|Out-Null;try{$x=Invoke-DINPPV010 -P $escape -PersistenceStore $outside}finally{if(Test-Path -LiteralPath $outside){[IO.Directory]::Delete($outside,$true)}};Assert-DINPPDenied $x 'path escape';Assert-DINPPTrue ([string]$x.reason -like '*path-denied:*escaped allowed root*') ('path escape reason '+[string]$x.reason);$count++

$key=New-DINPPFixtureV010 'wrong-key';$x=Invoke-DINPPV010 -P $key -Key $script:DINPIWrongKey;Assert-DINPPDenied $x 'wrong HMAC key';Assert-DINPPTrue ([string]$x.reason -like '*issuer-revalidation-denied:*transaction-binding-hmac-mismatch') ('wrong key reason '+[string]$x.reason);$count++

$tamper=New-DINPPFixtureV010 'receipt-tamper';$bad=Copy-DINPP $tamper.reservation;$bad.receipt.new_permit_transaction_id=Get-DINPIANewTransactionId 'persistence-transplant';$bad.receipt.reservation_fingerprint=Get-CustomAppProductionDualIdNewPermitReservationSha256V010(Get-CustomAppProductionDualIdNewPermitReservationReceiptMaterialV010 -Receipt $bad.receipt);$x=Invoke-DINPPV010 -P $tamper -ReservationResult $bad;Assert-DINPPDenied $x 'reservation transplant';Assert-DINPPTrue ([string]$x.reason -like '*reservation-issuer-continuity-new_permit_transaction_id-mismatch') ('reservation transplant reason '+[string]$x.reason);$count++

$drift=New-DINPPFixtureV010 'live-drift';$baseline=Copy-DINPP $drift.q.i.f.live.baseline;$baseline.tree_sha256=('8'*64);$x=Invoke-DINPPV010 -P $drift -CurrentBaseline $baseline;Assert-DINPPDenied $x 'pre-write live drift';Assert-DINPPTrue ([string]$x.reason -like '*pre-admission-denied:*') ('live drift reason '+[string]$x.reason);$rp=Get-CustomAppProductionDualIdNewPermitReservationPersistencePathsV010 -AllowedRoot $drift.q.i.f.q.x.f.trust -PersistenceStoreDirectory $drift.store;Assert-DINPPFalse (Test-Path -LiteralPath $rp.current) 'live drift wrote current';$count++

$post=New-DINPPFixtureV010 'post-write-drift';$F=$post.q.i.f;$pre=Resolve-CustomAppProductionDualIdNewPermitIssuanceAdmissionV010 -Name ([string]$F.q.bundle.lifecycle.name) -LifecycleRow $F.q.bundle.lifecycle -ProvenanceRow $F.q.bundle.provenance -BindingRow $F.q.bundle.binding -StageResult $F.q.bundle.stage -ShadowResult $F.q.bundle.shadow -HousekeepingResult $F.q.house.result -AllowedRoot $F.q.x.f.trust -StoreDirectory $F.q.x.f.store -HistoricalPermitTransactionId ([string]$F.q.house.result.permit_transaction_id) -HistoricalJournalTransactionId ([string]$F.q.house.result.journal_transaction_id) -NewPermitTransactionId ([string]$F.new_id) -LocalAppDataRoot ([string]$F.q.x.f.x.fixture.q.persistence.local) -AppDataRoot ([string]$F.q.x.f.x.fixture.q.persistence.roaming) -CurrentBaseline $F.live.baseline -ShadowProtocolQualification $F.live.shadow -LiveAttestedQualification $F.live.live -PriorReadinessReceipt $F.prior -Now $post.at
Assert-DINPPTrue ([bool]$pre.ok) 'post-write drift fixture admission failed';$script:DINPPPre=Copy-DINPP $pre.receipt;$script:DINPPPost=Copy-DINPP $pre.receipt;$script:DINPPPost.checked_at=([DateTimeOffset]::Parse([string]$script:DINPPPost.checked_at).AddMilliseconds(1)).ToUniversalTime().ToString('o');$script:DINPPPost.issuance_admission_fingerprint=Get-CustomAppProductionDualIdNewPermitIssuanceAdmissionSha256V010(Get-CustomAppProductionDualIdNewPermitIssuanceAdmissionMaterialV010 $script:DINPPPost);$script:DINPPCalls=0;$orig=(Get-Command Resolve-CustomAppProductionDualIdNewPermitIssuanceAdmissionV010 -CommandType Function).ScriptBlock
try{Set-Item -Path Function:\Resolve-CustomAppProductionDualIdNewPermitIssuanceAdmissionV010 -Value {param($Name,$LifecycleRow,$ProvenanceRow,$BindingRow,$StageResult,$ShadowResult,$HousekeepingResult,$AllowedRoot,$StoreDirectory,$HistoricalPermitTransactionId,$HistoricalJournalTransactionId,$NewPermitTransactionId,$LocalAppDataRoot,$AppDataRoot,$CurrentBaseline,$ShadowProtocolQualification,$LiveAttestedQualification,$PriorReadinessReceipt,$Now,$MaxRemoteObservationAgeHours);$script:DINPPCalls++;if($script:DINPPCalls -eq 1){return [pscustomobject]@{ok=$true;reason='fixture-pre';receipt=$script:DINPPPre}};return [pscustomobject]@{ok=$true;reason='fixture-post';receipt=$script:DINPPPost}};$x=Invoke-DINPPV010 $post}finally{Set-Item -Path Function:\Resolve-CustomAppProductionDualIdNewPermitIssuanceAdmissionV010 -Value $orig;$script:DINPPCalls=0}
Assert-DINPPDenied $x 'post-write drift';Assert-DINPPTrue ([bool]$x.reservation_persisted) 'post-write drift lost durable write state';Assert-DINPPEq $x.reason 'dual-id-reservation-persistence-admission-drift-after-durable-write' 'post-write drift reason';$retry=Invoke-DINPPV010 -P $post -At $post.at.AddMilliseconds(200);Assert-DINPPTrue ([bool]$retry.ok) ('post-write drift recovery retry denied: '+[string]$retry.reason);Assert-DINPPTrue ([bool]$retry.store.recovered_existing_persistence) 'post-write drift retry not recovered';$count++

$conflictA=New-DINPPFixtureV010 'conflict-a';$okA=Invoke-DINPPV010 $conflictA;Assert-DINPPTrue ([bool]$okA.ok) 'conflict setup persist failed'
$conflictB=New-DINPPFixtureV010 'conflict-b';$secondReservation=Invoke-DINPRV010 -Q $conflictB.q -At $conflictB.q.at.AddMilliseconds(100);Assert-DINPPTrue ([bool]$secondReservation.ok) ('same-root second reservation setup denied: '+[string]$secondReservation.reason);Assert-DINPPFalse (([string]$secondReservation.receipt.reservation_fingerprint)-ceq([string]$conflictB.reservation.receipt.reservation_fingerprint)) 'same-root second reservation did not produce distinct evidence';$conflictB.reservation=$secondReservation;$conflictB.at=$conflictB.q.at.AddMilliseconds(600);$conflictB.store=$conflictA.store;$x=Invoke-DINPPV010 $conflictB;Assert-DINPPDenied $x 'same revision different state conflict';Assert-DINPPTrue ([string]$x.reason -like '*existing-revision-conflict*') ('conflict reason '+[string]$x.reason);$count++

$envTamper=New-DINPPFixtureV010 'envelope-tamper';$ok=Invoke-DINPPV010 $envTamper;Assert-DINPPTrue ([bool]$ok.ok) 'envelope tamper setup failed';$ep=Get-CustomAppProductionDualIdNewPermitReservationPersistencePathsV010 -AllowedRoot $envTamper.q.i.f.q.x.f.trust -PersistenceStoreDirectory $envTamper.store;$historyFile=@(Get-ChildItem -LiteralPath $ep.history -File -Filter '*.json')[0];$raw=[IO.File]::ReadAllText($historyFile.FullName,[Text.UTF8Encoding]::new($false));$obj=$raw|ConvertFrom-Json;$obj.new_permit_transaction_id=('f'*64);[IO.File]::WriteAllText($historyFile.FullName,($obj|ConvertTo-Json -Depth 100 -Compress),[Text.UTF8Encoding]::new($false));$denied=$false;try{[void](Read-CustomAppProductionDualIdNewPermitReservationStoreV010 -AllowedRoot $envTamper.q.i.f.q.x.f.trust -PersistenceStoreDirectory $envTamper.store)}catch{$denied=$true;Assert-DINPPTrue ([string]$_.Exception.Message -like '*envelope*invalid*') ('tamper read reason '+[string]$_.Exception.Message)};Assert-DINPPTrue $denied 'tampered durable envelope was accepted';$count++

$receiptTamper=Copy-DINPP $validResult.receipt;$receiptTamper.permit_consumed=$true;$receiptTamper.persistence_fingerprint=Get-CustomAppProductionDualIdNewPermitReservationPersistenceSha256V010(Get-CustomAppProductionDualIdNewPermitReservationPersistenceReceiptMaterialV010 -Receipt $receiptTamper);$ck=Test-CustomAppProductionDualIdNewPermitReservationPersistenceReceiptV010 -Receipt $receiptTamper;Assert-DINPPFalse ([bool]$ck.ok) 'consumed persistence receipt tamper accepted';Assert-DINPPTrue ([string]$ck.reason -like '*authority-escaped-permit_consumed') 'consumed receipt tamper reason';$count++

if($count -ne 12){throw "dual-ID reservation persistence matrix count mismatch $count"}
Write-Host "CUSTOM_APP_PRODUCTION_DUAL_ID_NEW_PERMIT_RESERVATION_PERSISTENCE_MATRIX_PASS cases=$count durable_history=true crash_pointer_repair=true triple_id_evidence=true transaction_hmac_durable=true session_key_persisted=false permit_consumed=false zero_authority=true"